What integer is printed by the following C code?
```c
#include <stdio.h>
int main() {
    int a[] = {2, 4, 6, 8, 10};
    int *p = a + 4;
    printf("%d", p[-2] + *(a + 1));
    return 0;
}
```

What integer is printed by the following C code?
```c
#include <stdio.h>
int main() {
    unsigned int x = 13;
    printf("%u", (x << 2) ^ (x >> 1));
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int sum_even(int a[], int n) {
    if (n == 0) return 0;
    return ((a[n - 1] % 2 == 0) ? a[n - 1] : 0) + sum_even(a, n - 1);
}
int main() {
    int a[] = {3, 8, 5, 12, 7, 4};
    printf("%d", sum_even(a, 6));
    return 0;
}
```

What is the output of the following C program?
```c
#include <stdio.h>
int main() {
    int a[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    int (*p)[3] = a + 1;
    printf("%d", *(*(p + 1) + 1));
    return 0;
}
```

What integer is printed by the following pseudocode under Call-by-Value-Result (copy-in, copy-out)?
```text
int x = 5;
void foo(int a) {
    x = x + 3;
    a = a + 2;
}
main() {
    foo(x);
    print(x);
}
```
